import { describe, expect, it } from "vitest";
import { tagReplayCommand } from "./replaySessionTag.js";
describe("tagReplayCommand", () => {
    it("exports the session id before a replay command", () => {
        expect(tagReplayCommand("pnpm exec bitfab-replay --registry scripts/replayRegistry.ts summarize", "T-0f3c")).toBe("export AGENT_SESSION_ID='T-0f3c'; pnpm exec bitfab-replay --registry scripts/replayRegistry.ts summarize");
    });
    it("tags a Go registry replay", () => {
        expect(tagReplayCommand("go run ./cmd/registry summarize", "T-1")).toBe("export AGENT_SESSION_ID='T-1'; go run ./cmd/registry summarize");
    });
    it("leaves other commands alone", () => {
        expect(tagReplayCommand("pnpm test", "T-1")).toBeNull();
    });
    it("leaves a command that already names a session alone", () => {
        expect(tagReplayCommand("AGENT_SESSION_ID=abc bitfab-replay x", "T-1")).toBeNull();
        expect(tagReplayCommand("bitfab-replay x --agent-session-id abc", "T-1")).toBeNull();
    });
    it("refuses an id that could break out of the quotes", () => {
        expect(tagReplayCommand("bitfab-replay x", "a'; rm -rf ~; '")).toBeNull();
    });
});
